def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    H = int(data[0])
    W = int(data[1])
    K = int(data[2])
    S = data[3:H+3]

    dic = {'o': 0, 'x': 1, '.': 2}
    min_operations = 10**10

    for i in range(H):
        if W < K:
            continue
        chk = [0, 0, 0]
        for j in range(K):
            chk[dic[S[i][j]]] += 1
        if chk[1] == 0:
            min_operations = min(min_operations, chk[2])
        for j in range(K, W):
            chk[dic[S[i][j-K]]] -= 1
            chk[dic[S[i][j]]] += 1
            if chk[1] == 0:
                min_operations = min(min_operations, chk[2])

    for j in range(W):
        if H < K:
            continue
        chk = [0, 0, 0]
        for i in range(K):
            chk[dic[S[i][j]]] += 1
        if chk[1] == 0:
            min_operations = min(min_operations, chk[2])
        for i in range(K, H):
            chk[dic[S[i-K][j]]] -= 1
            chk[dic[S[i][j]]] += 1
            if chk[1] == 0:
                min_operations = min(min_operations, chk[2])

    if min_operations == 10**10:
        print(0)
    else:
        print(min_operations)
